# Los números se cuentan aquí mismo sobre las Biblias del app; las referencias se validan en curiosidades.py.
def _vers(B,i):return sum(len(c) for c in B[i])
_rank=lambda B,rg:sorted(((_vers(B,i),i) for i in rg),reverse=True)
_tRV,_tBL=_rank(RV,range(66)),_rank(BL,range(66))
_nRV,_nBL=_rank(RV,range(39,66)),_rank(BL,range(39,66))
assert _tRV[:3]==_tBL[:3] and [i for _,i in _tRV[:3]]==[18,0,23] and _nRV[0]==_nBL[0] and _nRV[0][1]==41
jRV,_=phrase(RV,r'\bjes[uú]s\b');jcRV,_=phrase(RV,r'\bjesucristo\b');jBL,_=phrase(BL,r'\bjesus\b')
aRV,avRV=phrase(RV,r'\bamor\b');aBL,avBL=phrase(BL,r'\bamor\b')
hRV,hvRV=phrase(RV,r'\baleluya\b');hBL,hvBL=phrase(BL,r'\baleluia\b')
_lib=lambda vs:sorted({int(r.split('.')[0]) for r in vs})
assert _lib(hvRV)==[18,65] and _lib(hvBL)==[18,65]
hRVs=sum(1 for r in hvRV if r.startswith('18.'));hBLs=sum(1 for r in hvBL if r.startswith('18.'))
assert hRV==len(hvRV) and hBL==len(hvBL)
tRV,_=phrase(RV,r'\bno temas\b');tpRV,_=phrase(RV,r'\bno tem[aá]is\b')
tBL,_=phrase(BL,r'\bnão temas\b');tpBL,_=phrase(BL,r'\bnão temais\b')
